-- --- assert -------------------------------------------------------------------
do $$
declare n int;
begin
  select count(*) into n from public.pooja_steps
   where pooja_id = 'ganesha_standard'
     and (philosophy_en is null or btrim(philosophy_en) = '');
  if n > 0 then raise exception '% Ganesha steps still have no philosophy_en', n; end if;
  -- No two steps IN THE SAME POOJA may share it: a copy-paste there is
  -- invisible on screen. Across poojas sharing is correct and deliberate --
  -- the purvangam belongs to the act, not the deity, so Achamanam, Anga
  -- Vandanam, Vighneshwara Dhyanam, Pranayamam, Ghanta Pooja and Kalasha Pooja
  -- each carry one explanation used by both. The first version of this check
  -- was unscoped and failed on exactly those six.
  select count(*) into n from (
    select pooja_id, philosophy_en from public.pooja_steps
     where philosophy_en is not null group by 1, 2 having count(*) > 1) x;
  if n > 0 then raise exception '% philosophy texts are shared within one pooja', n; end if;
end $$;


